import type { APIRoute } from 'astro';
import { SITE_URL } from '../i18n/routes';

/*
 * /sitemap.xml: the address people and tools try first. The real sitemap is generated by
 * @astrojs/sitemap as /sitemap-index.xml (+ /sitemap-0.xml with all 12 pages and hreflang pairs);
 * this file is the same index under the conventional name, so both addresses work in Search Console.
 */
const INDEX = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><sitemap><loc>${SITE_URL}/sitemap-0.xml</loc></sitemap></sitemapindex>
`;

export const GET: APIRoute = () =>
  new Response(INDEX, { headers: { 'Content-Type': 'application/xml; charset=utf-8' } });
